var t=[{title:`Resultaatdoelen en procesdoelen`,text:`Een resultaatdoel benoemt het resultaat dat je wilt, bijvoorbeeld acht beheerste push-ups of 30 minuten wandelen zonder te stoppen. Een procesdoel benoemt het gedrag dat je daar brengt, zoals twee krachtsessies per week. Resultaten motiveren je, en processen geven je het dagelijkse plan.`},{title:`SMART-doelen`,text:`Een praktisch doel is specifiek, meetbaar, haalbaar, relevant en tijdgebonden. „Fit worden” is te vaag. Probeer: „zes weken lang twee full-body-trainingen van 30 minuten per week doen en mijn comfortabele ononderbroken wandeling opbouwen van 10 naar 20 minuten.” Je precieze doel moet afhangen van je huidige vermogen, gezondheid en agenda.`},{title:`Stel een uitgangspunt vast`,text:`Leg voordat je begint iets vast dat je kunt herhalen: de push-upvariant die je met goede vorm kunt doen, het gewicht en de herhalingen bij een bekende beweging, of hoe lang je comfortabel kunt wandelen. Vergelijk gelijke dingen. Veel beginners verbeteren merkbaar in de eerste weken, maar veranderingen in kracht en lichaamssamenstelling lopen sterk uiteen, dus niemand kan betrouwbaar een bepaald tempo van spiergroei of vetverlies beloven.`},{title:`Plan voor onderbrekingen`,text:`Bepaal een minimale versie van het doel voor drukke weken, zoals een kortere training in plaats van een overgeslagen sessie. Stel niet meerdere agressieve doelen tegelijk. Als een doel zo moeilijk is dat het een onveilig tempo of te veel trainingsvolume vraagt, maak het dan kleiner.`},{title:`Evalueren en bijsturen`,text:`Beoordeel ongeveer elke vier tot acht weken opnieuw. Als je je aan het plan houdt maar de vooruitgang traag is, verander dan één trainingsvariabele of geef jezelf meer tijd. Als je sessies blijft missen, los dan het schema op voordat je oefeningen toevoegt.`},{title:`TrainUp gebruiken`,text:`Je doel, trainingsdagen en sessieduur staan in Profiel. Tijdens elke training vink je sets af en leg je je herhalingen vast, en daarna beoordeel je je inspanning. Geschiedenis laat dan zien of je procesdoel week na week lukt.`}];var a=[{label:`CDC: beginnen met en volhouden van activiteit`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};